import itertools

def is_good_function(g_dict, domain):
    # g_dict is a dictionary mapping x to g(x)
    # domain is the set of all x used in the dictionary

    # (3) g(1) = 1
    if g_dict.get(1) != 1:
        return False

    # (1) For any two distinct real numbers a, b, if g(ab) = 0, then g(a) = 0 or g(b) = 0.
    # (2) For any two distinct real numbers a, b, if g(ab) != 0, then (g(a)-g(b))/(a-b) = (g(a)g(b))/g(ab).

    for a in domain:
        for b in domain:
            if a == b:
                continue

            ab = a * b
            if ab not in domain:
                continue

            ga = g_dict[a]
            gb = g_dict[b]
            gab = g_dict[ab]

            # (1)
            if gab == 0:
                if ga != 0 and gb != 0:
                    return False
            # (2)
            else:
                # Check (ga - gb) / (a - b) == (ga * gb) / gab
                # Use (ga - gb) * gab == ga * gb * (a - b) to avoid division
                if abs((ga - gb) * gab - ga * gb * (a - b)) > 1e-9:
                    return False

    return True

# Let's test some functions of the form g(x) = x for x in G, 0 otherwise.
domain = [1, 2, 3, 4, 6, 8, 9, 12]
subsets = []
import itertools
import itertools as it

# Generating all possible G (subgroups of the domain)
# For our purpose, let's just check all subsets G that contain 1.
for r in range(1, len(domain) + 1):
    for subset in it.combinations(domain, r):
        if 1 in subset:
            g_dict = {x: (x if x in subset else 0) for x in domain}
            if is_good_function(g_dict, domain):
                subsets.append(set(subset))

print(len(subsets))
for s in subsets:
    print(s)
